/**
 * Precomputed equirectangular landmask (360x180 resolution) derived from Natural Earth 110m land polygons.
 * Compressed via Run-Length Encoding and Base64 (only ~4.7 KB).
 * Decompresses in <0.2ms into a fast Uint8Array lookup.
 */

const RLE_BASE64 = '';
const RLE_START_VAL = 0;
const GRID_WIDTH = 720;
const GRID_HEIGHT = 360;

let cachedLandMask = null;

export function getLandMask() {
  if (cachedLandMask) return cachedLandMask;

  const binary = atob(RLE_BASE64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  const rle = new Uint16Array(bytes.buffer, bytes.byteOffset, bytes.byteLength / 2);

  const grid = new Uint8Array(GRID_WIDTH * GRID_HEIGHT);
  let curVal = RLE_START_VAL;
  let idx = 0;
  for (let i = 0; i < rle.length; i++) {
    const count = rle[i];
    for (let c = 0; c < count; c++) {
      grid[idx++] = curVal;
    }
    curVal = curVal === 0 ? 1 : 0;
  }

  cachedLandMask = grid;
  return grid;
}

export function isLand(lat, lon) {
  const mask = getLandMask();
  let normLon = ((lon + 180) % 360 + 360) % 360 - 180;
  const x = Math.min(GRID_WIDTH - 1, Math.max(0, Math.floor((normLon + 180) * (GRID_WIDTH / 360))));
  const y = Math.min(GRID_HEIGHT - 1, Math.max(0, Math.floor((90 - lat) * (GRID_HEIGHT / 180))));
  return mask[y * GRID_WIDTH + x] === 1;
}

